// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Função para formatar valores em moeda local
function formatCurrency(value) {
  return "R$ " + value.toLocaleString("pt-BR", {minimumFractionDigits: 2});
}

// Dados dos investimentos
const investimentos = $input.first().json.investimentos;

// Dados dos clientes
const clientes = $input.first().json.body.clientes;

// Processamento
const resultados = clientes.map(cliente => {
  const saldo_num = parseFloat(
    cliente.saldo.replace("R$", "").replace(/\./g, "").replace(",", ".")
  );

  const produtosPerfil = investimentos.filter(inv => inv.perfil === cliente.perfil);
  const produtoEscolhido = produtosPerfil
    .filter(p => saldo_num >= p.minimo)
    .sort((a, b) => b.minimo - a.minimo)[0];

  if (!produtoEscolhido) {
    return {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo_texto: cliente.saldo,
      saldo_num,
      motivo: "saldo_insuficiente",
      mensagem_escolhida: `Olá ${cliente.nome}, infelizmente seu saldo atual (${cliente.saldo}) não permite investir nos produtos disponíveis para seu perfil (${cliente.perfil}).`
    };
  }

  const minimoFormatado = formatCurrency(produtoEscolhido.minimo);
  const rentabilidade = produtoEscolhido.rentabilidade;

  const perfilNormalizado = cliente.perfil.toLowerCase();

  const mensagens = {
    conservador: `Olá ${cliente.nome}! Como seu perfil é (${cliente.perfil}), o foco é a segurança do seu patrimônio. Indicamos o produto **${produtoEscolhido.produto}** (mínimo ${minimoFormatado}) em renda fixa para rentabilizar com proteção. Com seu saldo atual (${cliente.saldo}), você já pode começar. Rentabilidade esperada: ${rentabilidade}.`,

    moderado: `Olá ${cliente.nome}! Para o seu perfil (${cliente.perfil}), buscamos o equilíbrio ideal entre renda fixa e variável. Uma excelente oportunidade é o **${produtoEscolhido.produto}** (mínimo ${minimoFormatado}), combinando segurança e retorno. Seu saldo atual (${cliente.saldo}) permite aplicar agora mesmo. Rentabilidade: ${rentabilidade}.`,

    arrojado: `Olá ${cliente.nome}! Sendo seu perfil (${cliente.perfil}), o objetivo é potencializar seus ganhos com foco em ações e renda variável. Sugerimos o produto **${produtoEscolhido.produto}** (mínimo ${minimoFormatado}) para buscar maior retorno. Com o seu saldo atual (${cliente.saldo}), você já está pronto para investir. Rentabilidade: ${rentabilidade}.`
  };

  const mensagem_escolhida = mensagens[perfilNormalizado];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: cliente.saldo,
    saldo_num,
    recomendacao: {
      perfil: produtoEscolhido.perfil,
      produto: produtoEscolhido.produto,
      minimo: produtoEscolhido.minimo,
      rentabilidade
    },
    motivo: "saldo_ok",
    mensagem_escolhida
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];

// Função auxiliar para converter valores monetários em formato BRL para Number
function parseBRL(valor) {
  if (typeof valor === 'number') return valor;
  if (!valor) return 0;

  // Remove R$, espaços e caracteres não numéricos exceto pontos e vírgulas
  let limpo = String(valor).replace(/[^\d.,-]/g, '').trim();

  // Trata formato brasileiro (ex: 1.250,50 -> 1250.50)
  if (limpo.includes(',') && limpo.includes('.')) {
    limpo = limpo.replace(/\./g, '').replace(',', '.');
  } else if (limpo.includes(',')) {
    limpo = limpo.replace(',', '.');
  }

  const numero = parseFloat(limpo);
  return isNaN(numero) ? 0 : numero;
}

// Obtém o array de clientes do $json.resultados
const clientes = $json.resultados || [];

// Mapeia e padroniza cada cliente
const resultadosFormatados = clientes.map(cliente => {
  // Trata e converte o saldo
  const saldoNum = (cliente.saldo_num !== undefined && cliente.saldo_num !== null)
    ? Number(cliente.saldo_num)
    : parseBRL(cliente.saldo_texto || cliente.saldo);

  return {
    json: {
      email_to: String(cliente.email || '').trim(),
      nome: String(cliente.nome || '').trim(),
      perfil: cliente.perfil,
      saldo_texto: cliente.saldo_texto,
      saldo_num: saldoNum,
      recomendacao: cliente.recomendacao,
      motivo: cliente.motivo,
      mensagem_base: cliente.mensagem_escolhida || cliente.mensagem || '',
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return resultadosFormatados;

