return $input.all().map(item => {
  // Acessa o texto JSON dentro da estrutura correta
  const aiResponse = item.json.output[0].content[0].text;

  // Converte string JSON em objeto
  const parsed = JSON.parse(aiResponse);

  // Pega o e-mail do cliente (ajuste conforme seu fluxo)
  const to = parsed.email_to || "cliente@email.com";

  return {
    json: {
      ok: true,
      to,
      subject: parsed.subject,
      text_body: parsed.text_body,
      html_body: parsed.html_body
    }
  };
});
